import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`ai-deep-research`,heroTitle:`The #1 AI for Deep Research`,heroSubtitle:`Perplexity Computer scans hundreds of sources, cross-checks every claim, and delivers a cited research report.`,heroCta:`Get started`,hasInputUrl:!1,heroOverlaySteps:[`Breaking your question into sub-questions and search paths`,`Spinning up parallel agents across hundreds of sources`,`Cross-checking claims and scoring source quality`,`Cited deep research report with recommendations — ready to share`],generatingSteps:[`Analyzing your question and mapping the key unknowns`,`Designing an agent to search, read, and verify in parallel`,`Configuring multi-pass search loops with source verification`,`Setting up your report structure with citations and next steps`],featureSectionTitle:`From question to cited research report`,featureCardTitles:[`Connects to your research stack`,`Outputs you can act on`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Sheets, Google Docs, Notion, Slack, Google Drive — Computer plugs into your tools so findings land where your team already works.`,`Cited research reports. Market maps. Competitor breakdowns. Due diligence briefs. Recommendations backed by verified sources — not guesses.`],capabilitySectionTitle:`Your research team, on autopilot`,capabilitySectionSubtitle:`Ask your question, step away, come back to a fully cited research report.`,capabilityCards:[{title:`Due Diligence Reports`,description:`Computer can vet a company, founder, or deal — financials, filings, news, and red flags, all cited.`},{title:`Market Analysis`,description:`Computer can size a market, map the players, and track where it's heading — with sources for every number.`},{title:`Competitive Intelligence`,description:`Computer can monitor competitors' pricing, launches, and positioning — and report what changed and why it matters.`},{title:`Connect Your Tools`,description:`Computer can push findings to Google Sheets, Google Docs, Notion, and Slack — so research lands where your team already works.`},{title:`Remember & Learn`,description:`Computer can remember your company, your market, and past research — so every new question builds on the last.`},{title:`Monitor & Alert`,description:`Computer can re-run research on a schedule and alert you when the market shifts, a competitor moves, or new data drops.`}]});export{t as default};
